import{_ as t,o as i,c as s,a2 as a}from"./chunks/framework.BXzK3EA4.js";const r="/assets/Screenshot%202024-12-24%20at%202.49.27%E2%80%AFPM.DXyOWINP.png",o="/assets/Screenshot%202024-12-24%20at%202.49.44%E2%80%AFPM.BNAsX1MD.png",f=JSON.parse('{"title":"Firstock","description":"","frontmatter":{},"headers":[],"relativePath":"connect-brokers/brokers/firstock.md","filePath":"connect-brokers/brokers/firstock.md"}'),n={name:"connect-brokers/brokers/firstock.md"};function c(p,e,l,d,h,k){return i(),s("div",null,[...e[0]||(e[0]=[a('<h1 id="firstock" tabindex="-1">Firstock <a class="header-anchor" href="#firstock" aria-label="Permalink to &quot;Firstock&quot;">​</a></h1><p>Firstock is an Indian discount brokerage firm. Known for its user-friendly interface, Firstock provides mobile, web, and desktop platforms equipped with essential features like real-time market data, advanced charting tools, and order execution capabilities. Its competitive pricing structure and support for algorithmic trading make it an attractive option for both retail and professional traders.</p><p>Through Tradeboard, the Firstock plugin covers equity and equity derivatives on NSE and BSE. Currency (CDS) and commodity (MCX) segments are not part of this integration, so use a plugin that reports those exchanges if you trade them.</p><h2 id="getting-api-credentials" tabindex="-1">Getting API Credentials <a class="header-anchor" href="#getting-api-credentials" aria-label="Permalink to &quot;Getting API Credentials&quot;">​</a></h2><p>To integrate Firstock with Tradeboard, follow these steps to obtain your API key and secret:</p><p>1. Log in to Firstock Connect</p><p>• Visit <a href="https://connect.thefirstock.com/login?ref=wikiconnect.thefirstock.com" target="_blank" rel="noreferrer">https://connect.thefirstock.com/login?ref=wikiconnect.thefirstock.com</a>.</p><p>• Enter your Firstock login credentials.</p><p>2. Generate API Credentials:</p><figure><img src="'+r+'" alt=""><figcaption></figcaption></figure><p>• After logging in, navigate to the API Key section in your profile settings.</p><p>• Click on Generate API Key.</p><p>• Your Vendor Code and API Key will be displayed.</p><figure><img src="'+o+`" alt=""><figcaption></figcaption></figure><p>3. Configure Tradeboard:</p><p>• In your Tradeboard .env file, set the following variables:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_KEY</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Your Vendor Code&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">BROKER_API_SECRET</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;Your API Key&#39;</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">REDIRECT_URL</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> =</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;http://127.0.0.1:5000/firstock/callback&#39;</span></span></code></pre></div><h3 id="supported-exchanges" tabindex="-1">Supported Exchanges <a class="header-anchor" href="#supported-exchanges" aria-label="Permalink to &quot;Supported Exchanges&quot;">​</a></h3><p>Tradeboard reads this plugin&#39;s exchange list from <code>broker/firstock/plugin.json</code> and serves it to the app, so symbol search, the Strategy Builder and the tools pages only offer what the plugin actually handles.</p><ul><li><strong>Tradable:</strong> <code>NSE</code>, <code>BSE</code>, <code>NFO</code>, <code>BFO</code></li><li><strong>Index feeds:</strong> <code>NSE_INDEX</code></li></ul>`,20)])])}const u=t(n,[["render",c]]);export{f as __pageData,u as default};
